### Tier 3: Production Hardening (30 minutes)
**Objective**: Defense-in-depth with network segmentation, secrets management, audit logging, and monitoring

**What This Tier Adds:**
- Network segmentation (actuator on separate internal-only port)
- Secrets management (AWS Secrets Manager, not environment variables)
- Comprehensive audit logging with structured events
- Rate limiting on sensitive endpoints
- IP allowlisting for actuator access
- Prometheus metrics for security monitoring

**Implementation:**

```java
package com.example.security;

import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.config.http.SessionCreationPolicy;
import org.springframework.security.web.SecurityFilterChain;
import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter;
import org.springframework.boot.actuate.autoconfigure.security.servlet.EndpointRequest;
import io.github.bucket4j.Bucket;
import io.github.bucket4j.Bandwidth;
import java.time.Duration;

/**
 * TIER 3 SECURE: Production-grade defense-in-depth
 * 
 * Defenses:
 * - Multi-layer access control (network + application + data)
 * - Network segmentation (actuator on port 9090, firewall-restricted)
 * - Secrets management (AWS Secrets Manager, never in env vars)
 * - Rate limiting (20 requests/min on /admin)
 * - IP allowlisting for actuator endpoints
 * - Comprehensive audit logging
 * - Prometheus metrics for security monitoring
 * - Alerting on suspicious patterns
 * 
 * Time to implement: 30 minutes
 * Security posture: Enterprise-grade, compliant with NIST 800-53 AC-3
 */
@Configuration
@EnableMethodSecurity(prePostEnabled = true)
public class Tier3SecurityConfig {

    @Autowired
    private JwtAuthenticationFilter jwtAuthFilter;

    @Autowired
    private RateLimitingFilter rateLimitFilter;

    @Autowired
    private AuditLoggingFilter auditFilter;

    /**
     * Main application security (port 8080, public-facing)
     */
    @Bean
    @Order(1)
    public SecurityFilterChain apiSecurityFilterChain(HttpSecurity http) throws Exception {
        http
            .securityMatcher("/api/**", "/admin/**")
            .authorizeHttpRequests(authorize -> authorize
                .requestMatchers("/api/public/**").permitAll()
                .requestMatchers("/admin/**").hasRole("ADMIN")
                .anyRequest().authenticated()
            )
            .sessionManagement(session -> session
                .sessionCreationPolicy(SessionCreationPolicy.STATELESS)
            )
            .csrf(csrf -> csrf.disable())  // Stateless JWT
            .addFilterBefore(jwtAuthFilter, UsernamePasswordAuthenticationFilter.class)
            .addFilterBefore(rateLimitFilter, JwtAuthenticationFilter.class)
            .addFilterAfter(auditFilter, UsernamePasswordAuthenticationFilter.class)
            .headers(headers -> headers
                .frameOptions(frame -> frame.deny())
                .contentSecurityPolicy(csp -> csp.policyDirectives("default-src 'self'"))
            );

        return http.build();
    }

    /**
     * Actuator security (port 9090, internal-only)
     * Network-level restriction: Only accessible from VPC CIDR 10.0.0.0/16
     */
    @Bean
    @Order(2)
    public SecurityFilterChain actuatorSecurityFilterChain(HttpSecurity http) throws Exception {
        http
            .securityMatcher("/actuator/**")
            .authorizeHttpRequests(authorize -> authorize
                .requestMatchers("/actuator/health").permitAll()  // Load balancer health checks
                .requestMatchers("/actuator/**").access(new IpAddressAuthorizationManager("10.0.0.0/16"))  // Internal VPC only
            )
            .httpBasic(basic -> {});

        return http.build();
    }
}

/**
 * Rate limiting filter: 20 requests per minute on /admin endpoints
 */
@Component
class RateLimitingFilter extends OncePerRequestFilter {

    private final Map<String, Bucket> buckets = new ConcurrentHashMap<>();

    @Override
    protected void doFilterInternal(
        HttpServletRequest request,
        HttpServletResponse response,
        FilterChain filterChain
    ) throws ServletException, IOException {

        if (request.getRequestURI().startsWith("/admin")) {
            String clientId = getClientIdentifier(request);  // IP or user ID
            Bucket bucket = buckets.computeIfAbsent(clientId, k -> createBucket());

            if (!bucket.tryConsume(1)) {
                response.setStatus(429);  // Too Many Requests
                response.getWriter().write("{\"error\": \"Rate limit exceeded\"}");

                // Alert on rate limit violations (potential brute force)
                securityMetrics.increment("rate_limit_exceeded", "endpoint", request.getRequestURI());
                return;
            }
        }

        filterChain.doFilter(request, response);
    }

    private Bucket createBucket() {
        Bandwidth limit = Bandwidth.simple(20, Duration.ofMinutes(1));  // 20 requests/min
        return Bucket.builder().addLimit(limit).build();
    }

    private String getClientIdentifier(HttpServletRequest request) {
        // Prefer authenticated user ID over IP (IP can be shared via NAT)
        Authentication auth = SecurityContextHolder.getContext().getAuthentication();
        if (auth != null && auth.isAuthenticated()) {
            return auth.getName();
        }
        return request.getRemoteAddr();
    }
}

/**
 * Audit logging filter: Structured logging for all admin actions
 */
@Component
class AuditLoggingFilter extends OncePerRequestFilter {

    @Autowired
    private AuditEventRepository auditRepository;

    @Override
    protected void doFilterInternal(
        HttpServletRequest request,
        HttpServletResponse response,
        FilterChain filterChain
    ) throws ServletException, IOException {

        if (request.getRequestURI().startsWith("/admin") || request.getRequestURI().startsWith("/actuator")) {
            Instant startTime = Instant.now();
            String requestBody = extractRequestBody(request);

            filterChain.doFilter(request, response);

            // Log after request completes
            Authentication auth = SecurityContextHolder.getContext().getAuthentication();
            AuditEvent event = AuditEvent.builder()
                .timestamp(startTime)
                .actor(auth != null ? auth.getName() : "anonymous")
                .action(request.getMethod() + " " + request.getRequestURI())
                .sourceIp(request.getRemoteAddr())
                .userAgent(request.getHeader("User-Agent"))
                .requestBody(requestBody)
                .responseStatus(response.getStatus())
                .duration(Duration.between(startTime, Instant.now()).toMillis())
                .build();

            auditRepository.save(event);  // Persist to database or log aggregator

            // Alert on suspicious patterns
            if (auth == null && response.getStatus() == 403) {
                securityMetrics.increment("unauthorized_admin_access_attempt", "endpoint", request.getRequestURI());
            }
        } else {
            filterChain.doFilter(request, response);
        }
    }
}

/**
 * IP-based authorization manager for actuator endpoints
 */
class IpAddressAuthorizationManager implements AuthorizationManager<RequestAuthorizationContext> {

    private final IpAddressMatcher ipMatcher;

    public IpAddressAuthorizationManager(String cidr) {
        this.ipMatcher = new IpAddressMatcher(cidr);
    }

    @Override
    public AuthorizationDecision check(
        Supplier<Authentication> authentication,
        RequestAuthorizationContext context
    ) {
        HttpServletRequest request = context.getRequest();
        String remoteAddr = request.getRemoteAddr();

        boolean allowed = ipMatcher.matches(remoteAddr);

        if (!allowed) {
            // Log and alert on unauthorized access attempts
            log.warn("Actuator access denied from non-VPC IP: {}", remoteAddr);
            securityMetrics.increment("actuator_access_denied", "ip", remoteAddr);
        }

        return new AuthorizationDecision(allowed);
    }
}

/**
 * Secrets management: AWS Secrets Manager integration
 * Prevents secrets from appearing in /actuator/env
 */
@Configuration
class SecretsManagerConfig {

    @Bean
    public DataSource dataSource(SecretsManagerClient secretsClient) {
        // Retrieve secret from AWS Secrets Manager
        GetSecretValueRequest request = GetSecretValueRequest.builder()
            .secretId("prod/database/credentials")
            .build();

        GetSecretValueResponse response = secretsClient.getSecretValue(request);
        String secretString = response.secretString();

        // Parse JSON secret
        ObjectMapper mapper = new ObjectMapper();
        Map<String, String> credentials = mapper.readValue(secretString, Map.class);

        // Configure datasource with retrieved credentials
        HikariConfig config = new HikariConfig();
        config.setJdbcUrl(credentials.get("url"));
        config.setUsername(credentials.get("username"));
        config.setPassword(credentials.get("password"));  // Never in environment variables

        return new HikariDataSource(config);
    }
}

/**
 * Security metrics for Prometheus
 */
@Component
class SecurityMetrics {

    private final Counter authFailures;
    private final Counter rateLimitExceeded;
    private final Counter unauthorizedAdminAccess;
    private final Counter actuatorAccessDenied;
    private final Counter privilegeEscalationAttempts;

    public SecurityMetrics(MeterRegistry registry) {
        this.authFailures = Counter.builder("security_authentication_failures_total")
            .description("Total authentication failures")
            .register(registry);

        this.rateLimitExceeded = Counter.builder("security_rate_limit_exceeded_total")
            .description("Total rate limit violations")
            .tag("severity", "warning")
            .register(registry);

        this.unauthorizedAdminAccess = Counter.builder("security_unauthorized_admin_access_attempts_total")
            .description("Unauthorized admin endpoint access attempts")
            .tag("severity", "high")
            .register(registry);

        this.actuatorAccessDenied = Counter.builder("security_actuator_access_denied_total")
            .description("Actuator access denied (non-VPC IP)")
            .tag("severity", "critical")
            .register(registry);

        this.privilegeEscalationAttempts = Counter.builder("security_privilege_escalation_attempts_total")
            .description("Detected privilege escalation attempts")
            .tag("severity", "critical")
            .register(registry);
    }

    public void increment(String metricName, String... tags) {
        // Increment appropriate counter based on metric name
    }
}

