## Testing

### Test Suite: Comprehensive Security Validation

```java
package com.example.security;

import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.security.test.context.support.WithMockUser;
import org.springframework.test.web.servlet.MockMvc;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.csrf;

/**
 * Security test suite validating access control and CSRF protection
 */
@SpringBootTest
@AutoConfigureMockMvc
class SecurityConfigTest {

    @Autowired
    private MockMvc mockMvc;

    /**
     * TEST 1: Unauthenticated access to /admin/** must be blocked
     */
    @Test
    void testUnauthenticatedAdminAccessBlocked() throws Exception {
        mockMvc.perform(post("/admin/users/123/promote"))
            .andExpect(status().isUnauthorized());  // 401
    }

    /**
     * TEST 2: Unauthenticated access to /actuator/env must be blocked
     */
    @Test
    void testUnauthenticatedActuatorEnvBlocked() throws Exception {
        mockMvc.perform(get("/actuator/env"))
            .andExpect(status().isUnauthorized());  // 401
    }

    /**
     * TEST 3: Authenticated ADMIN can access /admin endpoints
     */
    @Test
    @WithMockUser(roles = "ADMIN")
    void testAdminCanAccessAdminEndpoints() throws Exception {
        mockMvc.perform(get("/admin/users"))
            .andExpect(status().isOk());  // 200
    }

    /**
     * TEST 4: Authenticated USER (non-admin) cannot access /admin endpoints
     */
    @Test
    @WithMockUser(roles = "USER")
    void testUserCannotAccessAdminEndpoints() throws Exception {
        mockMvc.perform(post("/admin/users/123/promote"))
            .andExpect(status().isForbidden());  // 403
    }

    /**
     * TEST 5: CSRF token required for POST requests (if not stateless)
     */
    @Test
    @WithMockUser(roles = "ADMIN")
    void testCsrfProtectionEnforced() throws Exception {
        // Without CSRF token (if csrf enabled)
        mockMvc.perform(post("/admin/users/123/promote"))
            .andExpect(status().isForbidden());  // 403 CSRF token missing

        // With CSRF token
        mockMvc.perform(post("/admin/users/123/promote").with(csrf()))
            .andExpect(status().isOk());  // 200
    }

    /**
     * TEST 6: /actuator/health is public but /actuator/env is protected
     */
    @Test
    void testActuatorHealthPublicButEnvProtected() throws Exception {
        mockMvc.perform(get("/actuator/health"))
            .andExpect(status().isOk());  // 200 - public

        mockMvc.perform(get("/actuator/env"))
            .andExpect(status().isUnauthorized());  // 401 - requires auth
    }

    /**
     * TEST 7: Rate limiting works (20 requests per minute to /admin)
     */
    @Test
    @WithMockUser(roles = "ADMIN")
    void testRateLimitingEnforced() throws Exception {
        // Send 21 requests (limit is 20)
        for (int i = 0; i < 21; i++) {
            var result = mockMvc.perform(get("/admin/users"));

            if (i < 20) {
                result.andExpect(status().isOk());  // First 20 succeed
            } else {
                result.andExpect(status().isTooManyRequests());  // 21st fails (429)
            }
        }
    }
}
```

